import sys

def is_valid(s):
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        else:
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def solve():
    s = sys.stdin.readline().strip()
    n = len(s)

    # Convert to integers: '(' -> 1, ')' -> -1
    arr = [1 if c == '(' else -1 for c in s]

    # Precompute prefix sums of the original array
    # pref[i] = sum(arr[0]...arr[i-1])
    pref = [0] * (n + 1)
    for i in range(n):
        pref[i+1] = pref[i] + arr[i]

    # Total sum must be even to be potentially valid
    total_sum = pref[n]
    if total_sum % 2 != 0:
        print("impossible")
        return

    # Iterate over all possible segments [l, r] (0-based indices)
    for l in range(n):
        for r in range(l, n):
            # Calculate the new total sum after inverting [l, r]
            # Inversion changes each element x to -x, so the change is -2*x
            segment_sum = pref[r+1] - pref[l]
            new_total = total_sum - 2 * segment_sum

            if new_total != 0:
                continue

            # Check validity of the new sequence
            # We need to check prefix sums for the modified sequence
            current_balance = 0
            valid = True

            for i in range(n):
                if i < l or i > r:
                    # Outside the segment, value remains same
                    val = arr[i]
                else:
                    # Inside the segment, value is inverted
                    val = -arr[i]

                current_balance += val
                if current_balance < 0:
                    valid = False
                    break

            if valid:
                print("possible")
                return

    print("impossible")

if __name__ == "__main__":
    solve()
